<script lang="ts">
 import {onMount} from 'svelte';
 import {Api} from './api';
 import type {LeaderboardData} from './types';
 let {connected,onprofile,onjoin,onmy}:{connected:boolean;onprofile:(handle:string)=>void;onjoin:()=>void;onmy:()=>void}=$props();
 let board=$state<LeaderboardData|null>(null);let offset=$state(0);let busy=$state(false);let error=$state('');let generation=0;
 async function load(next=offset){const current=++generation;busy=true;error='';try{const value=await new Api().leaderboard(next);if(current===generation){board=value;offset=next;}}catch(e){if(current===generation)error=e instanceof Error?e.message:'Could not load the leaderboard.';}finally{if(current===generation)busy=false;}}
 onMount(()=>{void load(0);return()=>{generation++;};});
</script>
<main class="library-page leaderboard-page"><div class="page-heading"><div><span class="eyebrow">GOOD STRUCTURES. SHARED PROGRESS.</span><h1>Leaderboard<span class="heading-dot">.</span></h1><p>Recognizing the people who give the next document a better start.</p></div><button class="primary" onclick={connected?onmy:onjoin}>{connected?'My points and rank →':'Create your free account →'}</button></div>
 <section class="board-intro"><div><span class="eyebrow">CONTRIBUTORS, RECOGNIZED</span><h2>A useful starting point<br/>can help someone else.</h2><p>Share a template worth reusing. Approved templates earn {board?.points_per_approval??20} points while they stay public.</p></div><div class="board-policy"><p><strong>Your choice to be public.</strong><span>Only members who enable their public profile appear here.</span></p><p><strong>Private overall rank.</strong><span>Your place among all contributors is shown only on My page.</span></p><p><strong>Tied points, shared rank.</strong><span>Points reflect templates that are currently public. Views and copies never earn points.</span></p></div></section>
 <div class="board-heading"><h2>Public contributors</h2>{#if board}<span>{board.total} {board.total===1?'contributor':'contributors'}</span>{/if}</div>
 {#if error}<div class="board-state" role="alert"><p>{error}</p><button class="secondary" onclick={()=>load()}>Retry leaderboard</button></div>
 {:else if busy}<div class="board-state" role="status">Loading public ranks…</div>
 {:else if board&&board.items.length}<div class="rank-table-wrap"><table><caption class="visually-hidden">Public contributor ranking</caption><thead><tr><th scope="col">Rank</th><th scope="col">Contributor</th><th scope="col" class="count-column">Approved templates</th><th scope="col" class="points-column">Points</th></tr></thead><tbody>{#each board.items as member (member.handle)}<tr class:leader={member.rank===1}><td><span class="rank">{member.rank}</span></td><td><button class="member-link" onclick={()=>onprofile(member.handle)}><span class="member-avatar" aria-hidden="true">{member.handle.slice(0,2).toUpperCase()}</span><strong>@{member.handle}</strong></button><small class="mobile-count">{member.approved_contributions} approved templates</small></td><td class="count-column">{member.approved_contributions}</td><td class="points-column"><strong>{member.total_points}</strong><span> pts</span></td></tr>{/each}</tbody></table></div>
 {:else}<section class="board-state empty-board" role="status"><span aria-hidden="true">↗</span><h2>The first good start could be yours.</h2><p>No public contributors are ranked yet. Share an original template, get it approved, and choose to show your profile.</p><button class="secondary" onclick={connected?onmy:onjoin}>{connected?'Set up my public profile →':'Join the community →'}</button></section>{/if}
 {#if board&&(offset>0||board.next_offset!==null)}<nav class="board-pagination" aria-label="Leaderboard pages"><button class="secondary" disabled={busy||offset===0} onclick={()=>load(Math.max(0,offset-20))}>← Previous</button><span>Page {Math.floor(offset/20)+1}</span><button class="secondary" disabled={busy||board.next_offset===null} onclick={()=>load(board!.next_offset!)}>Next →</button></nav>{/if}
 <p class="board-footnote">Public ranks include handles and contribution points. Your email, private references and documents stay in your own space.</p>
</main>
