e-height:1.8;color:#75816c}.empty-board{text-align:center;padding:50px 24px}.empty-board>span{font-size:30px;color:#779461}.empty-board h2{font-size:23px;color:#34583e;letter-spacing:-.5px}.empty-board p{max-width:440px;margin:14px auto 23px}.board-pagination{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:18px}.board-pagination>span{font-size:11px;color:#7d896e}.board-footnote{margin-top:22px}@media(max-width:800px){.board-intro{grid-template-columns:1fr;gap:20px;padding:28px}.board-intro h2{font-size:28px}.board-policy{gap:10px}.count-column{display:none}.mobile-count{display:block;font-size:9px;color:#839075;margin-top:7px;margin-left:51px}th,td{padding:14px 12px}.member-link{gap:9px}.member-avatar{width:30px;height:30px;font-size:9px}.mobile-count{margin-left:39px}.member-link strong{font-size:11px}.points-column>strong{font-size:16px}.rank{width:25px;height:25px;font-size:10px}}@media(max-width:380px){th,td{padding:12px 8px}.board-heading{align-items:flex-start;flex-direction:column;gap:0}.board-intro{padding:23px}.board-intro h2{font-size:24px}}
